-- ── OpenBI Marketing Demo: Massive MySQL Seed Data ──

CREATE TABLE marketing_campaigns (campaign_id INT AUTO_INCREMENT PRIMARY KEY, campaign_name VARCHAR(100) NOT NULL, channel VARCHAR(50) NOT NULL, target_client_type VARCHAR(50) NOT NULL);

CREATE TABLE client_acquisitions (acquisition_id INT AUTO_INCREMENT PRIMARY KEY, report_date DATE NOT NULL, campaign_id INT NOT NULL, marketing_spend DECIMAL(12,2) NOT NULL, impressions INT NOT NULL, clicks INT NOT NULL, new_leads INT NOT NULL, converted_clients INT NOT NULL, new_aum_acquired DECIMAL(15,2) NOT NULL, FOREIGN KEY (campaign_id) REFERENCES marketing_campaigns(campaign_id));
CREATE INDEX idx_client_acq_date ON client_acquisitions(report_date);
CREATE INDEX idx_client_acq_camp ON client_acquisitions(campaign_id);

